<x-layouts.admin title="Add location">
    <div class="mb-7"><a href="{{ route('admin.locations.index') }}" class="text-sm font-bold text-indigo-700">← Locations</a><p class="mt-5 text-xs font-bold uppercase tracking-[.16em] text-indigo-600">Catalogue</p><h1 class="mt-1 text-2xl font-bold text-slate-950">Add a curated location</h1><p class="mt-2 text-sm text-slate-500">Find the place in Google, then choose how it appears and whether it may be used as a restricted pickup.</p></div>
    <form method="POST" action="{{ route('admin.locations.store') }}" class="admin-card overflow-hidden">@csrf
        <div class="border-b border-slate-100 p-6"><label class="admin-label">Search Google places</label><input id="location-search" class="admin-input" autocomplete="off" placeholder="e.g. Zurich Airport"><input type="hidden" id="google_place_id" name="google_place_id" value="{{ old('google_place_id') }}"><div id="location-results" class="mt-2 hidden overflow-hidden rounded-xl border border-slate-200 bg-white shadow-lg"></div><p id="location-selected" class="mt-2 text-sm font-semibold text-emerald-700"></p></div>
        <div class="grid gap-5 p-6 md:grid-cols-2"><div><label class="admin-label">Display name</label><input class="admin-input" name="name" value="{{ old('name') }}" placeholder="Uses Google name if empty"></div><div><label class="admin-label">URL slug</label><input class="admin-input" name="slug" value="{{ old('slug') }}" placeholder="Generated from name if empty"></div><div class="md:col-span-2"><label class="admin-label">Description</label><textarea class="admin-input min-h-24" name="description" placeholder="Short useful description for the website">{{ old('description') }}</textarea></div><div><label class="admin-label">Display order</label><input class="admin-input" type="number" min="0" name="sort_order" value="{{ old('sort_order', 0) }}"></div><div class="space-y-3 pt-7"><label class="flex items-center gap-3 text-sm font-semibold text-slate-700"><input type="hidden" name="is_active" value="0"><input type="checkbox" name="is_active" value="1" @checked(old('is_active', true))> Active and visible where used</label><label class="flex items-center gap-3 text-sm font-semibold text-slate-700"><input type="hidden" name="is_featured" value="0"><input type="checkbox" name="is_featured" value="1" @checked(old('is_featured'))> Show as a booking chip</label><label class="flex items-center gap-3 text-sm font-semibold text-slate-700"><input type="hidden" name="allowed_pickup" value="0"><input type="checkbox" name="allowed_pickup" value="1" @checked(old('allowed_pickup'))> Permit as restricted pickup</label></div></div>
        <div class="flex justify-end border-t border-slate-100 p-5"><button class="admin-button">Save location</button></div>
    </form>
    <script>(() => { const i=document.getElementById('location-search'), r=document.getElementById('location-results'), h=document.getElementById('google_place_id'), s=document.getElementById('location-selected'); let t; i.addEventListener('input',()=>{clearTimeout(t); if(i.value.trim().length<2){r.classList.add('hidden');return}t=setTimeout(async()=>{const q=encodeURIComponent(i.value);const x=await fetch(`{{ route('admin.locations.search') }}?q=${q}`,{headers:{Accept:'application/json'}});const j=await x.json();r.innerHTML=(j.data||[]).map(p=>`<button type="button" class="block w-full px-4 py-3 text-left text-sm hover:bg-slate-50" data-id="${p.place_id}" data-name="${p.name}">${p.name}</button>`).join('')||'<p class="px-4 py-3 text-sm text-slate-500">No places found.</p>';r.classList.remove('hidden')},300)});r.addEventListener('click',e=>{const b=e.target.closest('[data-id]');if(!b)return;h.value=b.dataset.id;s.textContent=`Selected: ${b.dataset.name}`;i.value=b.dataset.name;r.classList.add('hidden')})})();</script>
</x-layouts.admin>
